import { Component, computed, inject, signal, OnInit, OnDestroy } from '@angular/core';
import { ActivatedRoute, RouterLink } from '@angular/router';
import { SesionService } from '../../../shared/services/sesion.service';
import { AuthService } from '../../../services/auth.service';
import { PdfViewerComponent } from '../../../shared/components/pdf-viewer/pdf-viewer.component';
import { DocumentUploaderComponent } from '../../../shared/components/document-uploader/document-uploader';
import { SesionDetalle, SesionMiembro } from '../../../shared/models/sesion.model';
import { VistoBuenoDecision } from '../../../shared/models/visto-bueno.model';
import { extractErrorMessage } from '../../../shared/utils/error-utils';

@Component({
  selector: 'app-sesion-detalle',
  imports: [RouterLink, PdfViewerComponent, DocumentUploaderComponent],
  templateUrl: './sesion-detalle.component.html',
})
export class SesionDetalleComponent implements OnInit, OnDestroy {
  private readonly route = inject(ActivatedRoute);
  private readonly sesionService = inject(SesionService);
  private readonly authService = inject(AuthService);

  readonly sesionId = this.route.snapshot.paramMap.get('id') ?? '';
  readonly sesion = signal<SesionDetalle | null>(null);
  readonly isLoading = signal(true);
  readonly hasError = signal(false);
  readonly errorMessage = signal<string | null>(null);

  readonly selectedDocId = signal<number | null>(null);
  readonly selectedDocUrl = signal<string | null>(null);
  readonly selectedDocNombre = signal<string | null>(null);
  readonly decision = signal<VistoBuenoDecision>('aceptado');
  readonly observaciones = signal('');
  readonly evidenciaDocId = signal<number | null>(null);
  readonly submitting = signal(false);
  readonly submitSuccess = signal(false);
  readonly submitError = signal<string | null>(null);
  readonly tabActiva = signal<'documentos' | 'info'>('documentos');

  private readonly currentUserId = computed(() => this.authService.currentUser()?.id ?? null);
  private readonly isInternal = computed(() => {
    const role = this.authService.currentUser()?.role;
    return role === 'ejecutivo' || role === 'admin';
  });

  readonly estaCerrada = computed(() => this.sesion()?.status === 'cerrada');

  readonly isMember = computed(() => {
    const userId = this.currentUserId();
    const sesion = this.sesion();
    if (!userId || !sesion || !sesion.miembros) {
      return false;
    }
    return sesion.miembros.some(m => m.id === userId);
  });

  readonly yaDioVistoBueno = computed(() => {
    const userId = this.currentUserId();
    const sesion = this.sesion();
    if (!userId || !sesion || !sesion.miembros) {
      return false;
    }
    return sesion.miembros.some(m => m.id === userId && m.vistoBueno !== undefined);
  });

  readonly showVoteForm = computed(() => this.isMember() && !this.estaCerrada());
  readonly showRecommendation = computed(() => this.isInternal() && !this.isMember());
  readonly showCloseButton = computed(() => this.isInternal() && !this.estaCerrada());

  readonly recomendacionTexto = computed(() => {
    const sesion = this.sesion();
    if (!sesion) {
      return '';
    }
    const vistosBuenos = sesion.miembros.filter(m => m.vistoBueno);
    const total = vistosBuenos.length;
    if (total === 0) {
      return 'Sin vistos buenos registrados';
    }
    const aceptados = vistosBuenos.filter(m => m.vistoBueno?.decision === 'aceptado').length;
    const noAceptados = total - aceptados;
    return `Aceptado ${aceptados}/${total} · No aceptado ${noAceptados}/${total}`;
  });

  ngOnInit(): void {
    const id = Number(this.sesionId);
    if (!id) {
      this.isLoading.set(false);
      this.hasError.set(true);
      this.errorMessage.set('ID de sesión inválido.');
      return;
    }

    this.sesionService.getSesion(id).subscribe({
      next: (s) => {
        this.isLoading.set(false);
        this.sesion.set(s);
        const docs = s?.documentos ?? [];
        if (docs.length > 0) {
          this.selectedDocId.set(docs[0].id);
          this.selectedDocNombre.set(docs[0].nombre);
        } else {
          this.selectedDocId.set(null);
          this.selectedDocNombre.set(null);
        }
      },
      error: (err) => {
        this.isLoading.set(false);
        this.hasError.set(true);
        this.errorMessage.set(extractErrorMessage(err));
      },
    });
  }

  ngOnDestroy(): void {
    this.limpiarUrlPrevia();
  }

  seleccionarDocumento(id: number, nombre?: string): void {
    this.limpiarUrlPrevia();
    this.selectedDocUrl.set(null);
    this.selectedDocNombre.set(nombre ?? null);
    this.selectedDocId.set(id);
  }

  verArchivoEvidencia(file: File): void {
    this.limpiarUrlPrevia();
    const docId = this.evidenciaDocId();
    if (docId && file.slice().size === 0) {
      this.selectedDocUrl.set(null);
      this.selectedDocNombre.set(file.name);
      this.selectedDocId.set(docId);
    } else {
      const url = URL.createObjectURL(file);
      this.selectedDocUrl.set(url);
      this.selectedDocNombre.set(file.name);
      this.selectedDocId.set(null);
    }
  }

  verEvidencia(docId: number, nombre = 'evidencia.pdf'): void {
    this.seleccionarDocumento(docId, nombre);
  }

  private limpiarUrlPrevia(): void {
    const urlActual = this.selectedDocUrl();
    if (urlActual && urlActual.startsWith('blob:')) {
      URL.revokeObjectURL(urlActual);
    }
  }

  enviarVistoBueno(): void {
    const sesion = this.sesion();
    if (!sesion || this.submitting()) {
      return;
    }

    this.submitting.set(true);
    this.submitSuccess.set(false);
    this.submitError.set(null);

    this.sesionService
      .emitirVistoBueno(sesion.id, {
        decision: this.decision(),
        observaciones: this.observaciones() || undefined,
        evidenciaDocumentoId: this.evidenciaDocId() ?? undefined,
      })
      .subscribe({
        next: () => {
          this.submitting.set(false);
          this.submitSuccess.set(true);
          this.evidenciaDocId.set(null);
          this.reloadSesion(sesion.id);
        },
        error: (err) => {
          this.submitting.set(false);
          this.submitError.set(extractErrorMessage(err));
        },
      });
  }

  cerrarSesion(): void {
    const sesion = this.sesion();
    if (!sesion || this.submitting()) {
      return;
    }

    this.submitting.set(true);
    this.submitError.set(null);

    this.sesionService.cerrarSesion(sesion.id).subscribe({
      next: () => {
        this.submitting.set(false);
        this.reloadSesion(sesion.id);
      },
      error: (err) => {
        this.submitting.set(false);
        this.submitError.set(extractErrorMessage(err));
      },
    });
  }

  private reloadSesion(id: number): void {
    this.sesionService.getSesion(id).subscribe({
      next: (s) => {
        this.sesion.set(s);
        const userId = this.currentUserId();
        const miembro = s.miembros.find((m: SesionMiembro) => m.id === userId);
        if (miembro?.vistoBueno) {
          this.decision.set(miembro.vistoBueno.decision);
          this.observaciones.set(miembro.vistoBueno.observaciones ?? '');
        }
      },
      error: (err) => this.submitError.set(extractErrorMessage(err)),
    });
  }

  statusClass(status: string): string {
    switch (status) {
      case 'En Dictaminación':
        return 'bg-primary';
      case 'Enviada':
      case 'No Presentada':
        return 'bg-secondary';
      case 'Incompleta':
      case 'Suspendida':
        return 'bg-warning text-dark';
      case 'Subsanada':
        return 'bg-info text-dark';
      case 'Autorizada':
        return 'bg-success';
      case 'No Autorizada':
      case 'Revocada':
        return 'bg-danger';
      default:
        return 'bg-secondary';
    }
  }

  trackDoc(_index: number, doc: { id: number }): number {
    return doc.id;
  }

  trackMiembro(_index: number, m: { id: number }): number {
    return m.id;
  }
}
